pub fn drawFpsHud(io: std.Io) void {
    if (!z3d.fpsHudOn()) return;
    const now = std.Io.Clock.now(.awake, io).toMicroseconds();
    if (z3d.g_last_flush_us != 0) {
        const dt_us = now - z3d.g_last_flush_us;
        if (dt_us > 0) {
            const inst_fps = 1_000_000.0 / @as(f32, @floatFromInt(dt_us));
            z3d.g_fps_ema = if (z3d.g_fps_ema <= 0) inst_fps else z3d.g_fps_ema * 0.9 + inst_fps * 0.1;
        }
    }
    z3d.g_last_flush_us = now;
    var buf: [160]u8 = undefined;
    const line = std.fmt.bufPrint(&buf, "fps {d:.0}   draw {d}us   inst {d}   restage {d}   dc {d}", .{
        z3d.g_fps_ema, z3d.g_telemetry.draw_us, z3d.g_telemetry.instances, z3d.g_telemetry.staged_dynamic, z3d.g_telemetry.draw_calls,
    }) catch return;
    // Shadow + bright text so it reads over any background.
    core.drawTextLine(line, 9, 9, 14, 0, 0, 0, 0.8);
    core.drawTextLine(line, 8, 8, 14, 0.3, 1.0, 0.45, 1.0);
}

pub fn telemetryStats() z3d.TelemetryStats {
    return z3d.g_telemetry;
}
